-- Independent Phase 4A capability matrix and API privilege boundary.
BEGIN;
CREATE TEMP TABLE phase4a_security_assertions(label text PRIMARY KEY) ON COMMIT DROP;
CREATE FUNCTION pg_temp.check(label text,ok boolean) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL Phase4A security %',label;END IF;
 INSERT INTO pg_temp.phase4a_security_assertions VALUES(label);
END $$;
DO $$
DECLARE role_key text;expected text[];actual text[];tab record;fn record;client_role text;
 keys text[]:=ARRAY['announcements.send','communications.manage','communications.send','communications.view','delivery_history.view','moderation.manage','notifications.manage','notifications.view','team_chat.send','team_chat.view'];
BEGIN
 PERFORM pg_temp.check('exact evolved catalogs',
  (SELECT count(*)=21 FROM public.roles WHERE key not in('competition_manager','merchant_owner','merchant_admin','location_manager','offer_editor','redemption_clerk','sales_rep','regional_manager','support_reviewer')) AND (SELECT count(*)=44 FROM public.permissions WHERE key NOT IN ('attendance.view','attendance.respond','attendance.manage','attendance.checkin','volunteers.view','volunteers.signup','volunteers.manage','volunteers.assign','competition.view','competition.manage','competition.policy_manage','standings.view','standings.manage','standings.rebuild','leaderboard.view','leaderboard.manage','leaderboard.rebuild','records.view','records.manage','records.rebuild','athlete_profiles.view','athlete_profiles.manage','athlete_profiles.verify','recruiting_showcases.view','recruiting_showcases.manage','recruiting_showcases.publish','achievement_definitions.manage','awards.issue','awards.approve','fundraising.view','fundraising.create','fundraising.manage','fundraising.publish','fundraising.financial_view','money_board.view','money_board.manage','boss_bucks.view','boss_bucks.manage','boss_bucks.financial_view','boss_bucks.policy_manage','boss_bucks.membership_view','boss_bucks.membership_manage','boss_bucks.product_manage','boss_bucks.inventory_manage','boss_bucks.fulfillment_manage','boss_bucks.payment_reverse','payments.refund','payments.provider_manage','settlements.view','settlements.manage','settlements.reconcile','merchants.view','merchants.manage','merchants.access_manage','merchant_locations.view','merchant_locations.manage','merchant_offers.view','merchant_offers.manage','merchant_redemptions.view','merchant_redemptions.manage','merchant_reviews.manage','merchant_sales.view','merchant_sales.manage','partners.view','partners.configure','partners.contract_approve','partners.catalog_review','partners.integration_activate','partners.revenue_report') AND key NOT LIKE 'games.%')
  AND (SELECT count(*)=306 FROM public.role_permissions rp JOIN public.permissions p ON p.id=rp.permission_id WHERE p.key NOT IN ('attendance.view','attendance.respond','attendance.manage','attendance.checkin','volunteers.view','volunteers.signup','volunteers.manage','volunteers.assign','competition.view','competition.manage','competition.policy_manage','standings.view','standings.manage','standings.rebuild','leaderboard.view','leaderboard.manage','leaderboard.rebuild','records.view','records.manage','records.rebuild','athlete_profiles.view','athlete_profiles.manage','athlete_profiles.verify','recruiting_showcases.view','recruiting_showcases.manage','recruiting_showcases.publish','achievement_definitions.manage','awards.issue','awards.approve','fundraising.view','fundraising.create','fundraising.manage','fundraising.publish','fundraising.financial_view','money_board.view','money_board.manage','boss_bucks.view','boss_bucks.manage','boss_bucks.financial_view','boss_bucks.policy_manage','boss_bucks.membership_view','boss_bucks.membership_manage','boss_bucks.product_manage','boss_bucks.inventory_manage','boss_bucks.fulfillment_manage','boss_bucks.payment_reverse','payments.refund','payments.provider_manage','settlements.view','settlements.manage','settlements.reconcile','merchants.view','merchants.manage','merchants.access_manage','merchant_locations.view','merchant_locations.manage','merchant_offers.view','merchant_offers.manage','merchant_redemptions.view','merchant_redemptions.manage','merchant_reviews.manage','merchant_sales.view','merchant_sales.manage','partners.view','partners.configure','partners.contract_approve','partners.catalog_review','partners.integration_activate','partners.revenue_report') AND p.key NOT LIKE 'games.%')
  AND (SELECT count(*)=63 FROM pg_catalog.pg_tables WHERE schemaname='public' AND tablename NOT IN ('discount_campaign_products','discount_card_batches','discount_card_history','discount_entitlement_links','discount_fulfillment_history','discount_fulfillments','discount_intent_product_snapshots','discount_member_sources','discount_membership_history','discount_memberships','discount_order_history','discount_order_items','discount_orders','discount_physical_cards','discount_product_credits','discount_product_revisions','discount_products','discount_refund_items','discount_revision_events','discount_source_revocations','processing_accounts','payment_routing_revisions','payment_routing_events','settlement_policy_revisions','payment_checkouts','checkout_charge_allocations','boss_bucks_checkout_reservations','payment_checkout_events','provider_operations','provider_event_evidence','external_payment_tenders','saved_payment_methods','payment_execution_consents','payment_recurring_work','payment_history','payment_eligibility_commits','payment_attempt_invalidations','payment_review_cases','settlement_sources','settlement_events','settlement_accounts','settlement_journals','settlement_postings','settlement_requests','settlement_request_items','settlement_request_history','payment_refund_requests','external_payment_corrections','payment_dispute_cases','settlement_deficits','settlement_deficit_offsets','payment_reconciliation_runs','payment_reconciliation_items','boss_bucks_tenders','boss_bucks_consumptions','boss_bucks_restorations','boss_bucks_source_corrections','boss_bucks_recovery_claims','boss_bucks_recovery_movements','boss_bucks_wallets','boss_bucks_access','boss_bucks_policy_revisions','boss_bucks_fundraiser_bindings','boss_bucks_source_snapshots','boss_bucks_owner_resolutions','boss_bucks_accounts','boss_bucks_grants','boss_bucks_journals','boss_bucks_postings','boss_bucks_history','fundraising_campaigns','fundraising_targets','fundraising_fundraisers','fundraising_shares','money_boards','money_board_generations','money_board_tiles','fundraising_donors','money_board_reservations','fundraising_intents','fundraising_intent_events','fundraising_success_evidence','fundraising_recurring_commitments','fundraising_recurring_occurrences','fundraising_reward_qualifications','fundraising_history','merchant_markets','merchant_categories','merchants','merchant_modules','merchant_locations','merchant_access_assignments','merchant_staff_assignments','merchant_claims','merchant_history','merchant_sales_assignments','merchant_sales_leads','merchant_sales_activities','merchant_sales_history','merchant_offer_families','merchant_offer_revisions','merchant_offer_locations','merchant_offer_events','merchant_offer_local_state','merchant_favorites','merchant_redemptions','merchant_redemption_corrections','partner_providers','partner_config_revisions','partner_provider_events','partner_contract_revisions','partner_contract_events','partner_territories','partner_benefit_sources','partner_benefit_revisions','partner_benefit_reviews','partner_import_runs','partner_import_quarantine','partner_catalog_snapshots','partner_snapshot_items','partner_commission_policies','partner_transaction_sources','partner_transaction_events') AND tablename NOT IN ('competitions','competition_editions','competition_groups','competition_entries','competition_entry_groups','competition_access_assignments','standings_policy_revisions','competition_game_assignments','competition_game_assignment_groups','competition_rulings','ranking_definitions','ranking_scopes','standings_rows','ranking_candidates','record_events','record_current_holders','ranking_refresh_work','tournament_stages','tournament_brackets','tournament_bracket_revisions','tournament_seeds','tournament_matches','tournament_advancements','tournament_rulings') AND tablename NOT IN ('event_attendance_settings','attendance_responses','attendance_response_history','attendance_checkins','attendance_checkin_history','attendance_requests','volunteer_role_definitions','volunteer_shifts','volunteer_assignments','volunteer_assignment_history') AND tablename NOT IN ('game_sports','games','game_roster_snapshots','game_operator_assignments','game_operations','game_finalizations') AND tablename NOT IN ('game_basketball_states','game_basketball_events','game_basketball_lineups','game_basketball_lineup_history','game_basketball_finalizations','game_basketball_final_stats') AND tablename NOT IN ('game_soccer_states','game_soccer_events','game_soccer_lineups','game_soccer_finalizations','game_soccer_final_stats') AND tablename NOT IN ('game_football_states','game_football_events','game_football_lineups','game_football_finalizations','game_football_final_stats') AND tablename NOT IN ('game_diamond_states','game_diamond_events','game_diamond_plate_appearances','game_diamond_finalizations','game_diamond_final_stats') AND tablename NOT IN ('stat_competition_classifications','stat_game_selections','stat_game_contributions','stat_origin_summaries','stat_refresh_work') AND tablename NOT IN ('game_stat_catalog_versions','game_stat_catalog_items','game_tracking_profiles','game_tracking_profile_revisions','game_tracking_snapshots','game_stat_coverage_intervals','game_finalization_tracking_seals','game_volleyball_states','game_volleyball_events','game_volleyball_finalizations','game_volleyball_final_stats') AND tablename NOT IN ('athlete_profiles','athlete_profile_revisions','athlete_measurables','athlete_achievements','athlete_profile_verifications','athlete_media_links','recruiting_showcases','recruiting_showcase_revisions','recruiting_consents','recruiting_share_links','achievement_definitions','achievement_definition_revisions','entity_achievements','achievement_recognitions','achievement_history','achievement_display_choices','award_nominations','award_decisions','achievement_competition_closures','achievement_refresh_work')));
 PERFORM pg_temp.check('exact finite Phase4A permission catalog',(SELECT array_agg(key ORDER BY key)=keys FROM public.permissions WHERE key=ANY(keys)));
 FOR role_key IN SELECT key FROM public.roles ORDER BY key LOOP
  expected:=CASE
   WHEN role_key IN('super_administrator','platform_administrator','organization_owner','organization_administrator') THEN keys
   WHEN role_key='athletic_director' THEN ARRAY['announcements.send','communications.view']
   WHEN role_key IN('program_administrator','sport_administrator') THEN ARRAY['announcements.send','communications.manage','communications.send','communications.view','delivery_history.view','team_chat.send','team_chat.view']
   WHEN role_key='head_coach' THEN ARRAY['announcements.send','communications.manage','communications.view','team_chat.send','team_chat.view']
   WHEN role_key IN('assistant_coach','team_staff') THEN ARRAY['communications.view','team_chat.send','team_chat.view']
   ELSE ARRAY[]::text[] END;
  SELECT coalesce(array_agg(p.key ORDER BY p.key),ARRAY[]::text[]) INTO actual
   FROM public.roles r JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id
   WHERE r.key=role_key AND p.key=ANY(keys);
  PERFORM pg_temp.check('least privilege potential capability '||role_key,actual=expected);
 END LOOP;
 FOR tab IN SELECT n.nspname schema_name,c.relname name,c.oid,c.relrowsecurity
  FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
  WHERE c.relkind='r' AND n.nspname IN('public','boss_private')
   AND (c.relname LIKE 'communication_%' OR c.relname LIKE 'notification_%' OR c.relname='notifications') LOOP
  PERFORM pg_temp.check(tab.schema_name||'.'||tab.name||' RLS enabled',tab.relrowsecurity);
  FOREACH client_role IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
   PERFORM pg_temp.check(tab.schema_name||'.'||tab.name||' closed to '||client_role,
    NOT has_table_privilege(client_role,tab.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'));
  END LOOP;
 END LOOP;
 FOR fn IN SELECT p.oid,p.oid::regprocedure signature,p.prosecdef,p.proconfig,p.proacl,p.proowner,n.nspname schema_name,p.proname
  FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace
  WHERE (n.nspname='public' AND p.proname IN('boss_communications_read','boss_communications_mutate','boss_notifications_read','boss_notifications_mutate'))
   OR (n.nspname='boss_private' AND (p.proname LIKE 'comm_%' OR p.proname LIKE 'notification_%' OR p.proname IN('notifications_read','notifications_mutate'))) LOOP
  PERFORM pg_temp.check(fn.signature||' empty search_path',coalesce('search_path=""'=ANY(fn.proconfig),false));
  PERFORM pg_temp.check(fn.signature||' no PUBLIC execution',NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(fn.proacl,acldefault('f',fn.proowner))) a WHERE a.grantee=0 AND a.privilege_type='EXECUTE'));
  PERFORM pg_temp.check(fn.signature||' no anon/service execution',NOT has_function_privilege('anon',fn.oid,'EXECUTE') AND NOT has_function_privilege('service_role',fn.oid,'EXECUTE'));
  IF fn.schema_name='public' THEN
   PERFORM pg_temp.check(fn.signature||' public invoker only',NOT fn.prosecdef);
   PERFORM pg_temp.check(fn.signature||' authenticated entry',has_function_privilege('authenticated',fn.oid,'EXECUTE'));
  ELSIF fn.proname NOT IN('comm_read','comm_mutate','comm_storage_insert','comm_storage_select','notifications_read','notifications_mutate') THEN
   PERFORM pg_temp.check(fn.signature||' helper inaccessible to authenticated',NOT has_function_privilege('authenticated',fn.oid,'EXECUTE'));
  END IF;
 END LOOP;
 PERFORM pg_temp.check('new guardian capabilities default false and required',(SELECT count(*)=2 AND bool_and(a.attnotnull) AND bool_and(pg_get_expr(d.adbin,d.adrelid)='false') FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid='public.guardian_relationships'::regclass AND a.attname IN('can_receive_communications','can_send_communications')));
END $$;
SELECT count(*) AS passed_assertions FROM pg_temp.phase4a_security_assertions;
ROLLBACK;
